"""アプリのアイコン。Tk 既定の羽根の代わり。PNG は base64 で埋め込み。"""
from __future__ import annotations

import base64
import sys

_PNG_B64 = {
    16: "",
    32: "",
    64: "",
    128: "",
}


def apply_icon(root) -> None:
    """root と以降のダイアログ、タスクバーにアイコンを付ける。失敗しても無視。"""
    if sys.platform.startswith("win"):
        try:                                    # これがないとタスクバーで python.exe 扱いになる
            import ctypes
            ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID("pdetector.app")
        except Exception:
            pass
    try:
        import tkinter as tk
        imgs = [tk.PhotoImage(master=root, data=_PNG_B64[n]) for n in sorted(_PNG_B64, reverse=True)]
        root.iconphoto(True, *imgs)
        root._pid_icons = imgs                  # 参照を持っておかないと GC でアイコンが消える
    except Exception:
        pass
